INSERT INTO feature VALUES('work-pool','tooling','The work pool',NULL,'implemented','notable',NULL,'One driver-held pool starts its own workers, one for each thread of its width, on its first wide fork. The walk lowers and judges each component on it. The staging, the formatter, a package''s identity, the session''s form molding and its trials fork on it through the fork crate''s trait. The serial fork is the reference, and every width gives its result. The pool''s start costs more than rung 4 does at the default width. A dependence schedule hands its jobs over rings, one ring of jobs and one of results for each task, and an `each` hands each thread its share as one slice, so no hand-off takes a lock. A hand-off writes the job into an idle worker''s seat and allocates nothing, and a party takes back each part that no worker started, so a fork inside a job never waits for a worker that no party frees. A task with an empty ring polls on, and an idle worker spins, until the gap reaches the host''s park-to-wake cost; then the task leaves and the worker parks. The pool measures the cost at its start, and the driver keeps it in the state directory for each width. A spin budget adds polls before that; the calling thread spins up to the budget, then parks.','core-fork surface-dispatcher surface-session','crates/surface-driver/benches/hotpath.rs crates/surface-session/tests/trial.rs crates/surface-dispatcher/tests/package.rs::every_corpus_package_s_address_digests_each_source_s_closure_at_every_width_6406 crates/surface-dispatcher/tests/corpus.rs::every_width_composes_the_corpus_alike crates/surface-dispatcher/benches/schedule.rs crates/surface-driver/tests/cli.rs::a_staging_keeps_its_pool_s_park_cost_under_the_state_home',NULL,'#1250');
